create temporary view detail_data_${grass_region_without_quote} as
select
    user_id
    ,sum(home_dd_stay_impression_duration) as home_dd_stay_duration_1d
    ,sum(if(feature_detail = 'home-daily_discover-item',home_dd_ppv_duration,0)) as home_dd_pdp_duration_1d
    ,sum(mini_detail_feed_action_section_duration) as mini_detail_feed_section_duration_1d
    ,sum(if(source1_feature_detail = 'home-daily_discover-item_feed_card' and feature_detail = 'mini_detail_feed-mini_feed_item_card' ,mini_detail_feed_ppv_duration,0)) as mini_feed_pdp_duration_1d
    ,sum(if(source1_feature_detail = 'home-daily_discover-video' and feature_detail like 'video-%' ,home_dd_video_ppv_duration ,0)) as home_dd_video_pdp_duration_1d
    ,sum(if(source1_feature_detail = 'home-daily_discover-livestream' and feature_detail like 'streaming_room-%',home_dd_livestream_ppv_duration,0)) as home_dd_livestream_pdp_duration_1d
    ,sum(if(source1_feature_detail = 'home-daily_discover-item_mix_feed_card' and feature_detail like 'video-%' ,home_dd_video_ppv_duration ,0 )) as home_dd_item_mix_feed_pdp_duration_1d
    ,0 as dd_video_page_duration_1d
    ,0 as dd_livestream_page_duration_1d
    ,0 as dd_video_mix_feed_page_duration_1d
    ,0 as platform_page_duration
    ,0 as dd_video_landing_page_duration
    ,0 as dd_organic_item_pdp_duration_1d
    ,0 as dd_organic_item_mix_feed_pdp_duration_1d
    ,0 as dd_ads_item_pdp_duration_1d
    ,0 as dd_ads_item_mix_feed_pdp_duration_1d
    ,0 as dd_video_landing_livestream_duration_1d
    ,0 as dd_item_mix_landing_livestream_duration_1d
    ,0 as new_arrival_pdp_duration_1d
    ,0 as cheapest_pdp_duration_1d
from srdi_mart.dwm_sr_data_warehouse_platform_user_item
where
    local_date = ${local_date}
    and operation in ('click', 'ppv')
    and grass_region = ${grass_region}
group by user_id

union all

