    ,0 as dd_video_mix_feed_page_duration_1d
    ,0 as platform_page_duration
    ,0 as dd_video_landing_page_duration
    ,sum( case when (object in ('item card') or source1_object in ('item card') or source2_object in ('item card')) and  is_ads = false and  page_stay_duration >= 0 and page_stay_duration <= 60*60*1000 then  page_stay_duration else 0 end ) as dd_organic_item_pdp_duration_1d
    ,sum( case when (object in ('mix feed card') or source1_object in ('mix feed card') or source2_object in ('mix feed card')) and  is_ads = false and  page_stay_duration >= 0 and page_stay_duration <= 60*60*1000 then  page_stay_duration else 0 end ) as dd_organic_item_mix_feed_pdp_duration_1d
    ,sum( case when (object in ('item card') or source1_object in ('item card') or source2_object in ('item card')) and  is_ads = true and  page_stay_duration >= 0 and page_stay_duration <= 60*60*1000 then  page_stay_duration else 0 end ) as dd_ads_item_pdp_duration_1d
    ,sum( case when (object in ('mix feed card') or source1_object in ('mix feed card') or source2_object in ('mix feed card')) and  is_ads = true and  page_stay_duration >= 0 and page_stay_duration <= 60*60*1000 then page_stay_duration else 0 end ) as dd_ads_item_mix_feed_pdp_duration_1d
