insert overwrite table ${schema}.dws_sr_data_warehouse_homepage_user_duration_1d
partition(grass_region=${grass_region}, local_date=${local_date})
select
     user_id
    ,1.000*sum(home_dd_stay_duration_1d)/1000 as dd_cover_duration_1d
    ,1.000*sum(home_dd_pdp_duration_1d)/1000 as dd_pdp_duration_1d
    ,1.000*sum(mini_detail_feed_section_duration_1d)/1000 as dd_minifeed_duration_1d
    ,1.000*sum(dd_video_page_duration_1d)/1000 as dd_video_duration_1d
    ,sum(dd_livestream_page_duration_1d) as dd_live_duration_1d
    ,1.000*sum(dd_video_mix_feed_page_duration_1d)/1000 as dd_mixfeed_duration_1d
    ,1.000*sum(mini_feed_pdp_duration_1d)/1000 as dd_minifeed_pdp_duraion_1d
    ,1.000*sum(home_dd_video_pdp_duration_1d)/1000 as dd_video_pdp_duration_1d
    ,1.000*sum(home_dd_livestream_pdp_duration_1d)/1000 as dd_live_pdp_duration_1d
    ,1.000*sum(home_dd_item_mix_feed_pdp_duration_1d)/1000 as dd_mixfeed_pdp_duration_1d
    ,1.000*sum(platform_page_duration)/1000 as platform_duration_1d
    ,1.000*sum(dd_video_page_duration_1d)/1000 as dd_video_landing_page_duration
    ,1.000*sum(dd_organic_item_pdp_duration_1d)/1000 as dd_organic_item_pdp_duration_1d
    ,1.000*sum(dd_organic_item_mix_feed_pdp_duration_1d)/1000 as dd_organic_item_mix_feed_pdp_duration_1d
    ,1.000*sum(dd_ads_item_pdp_duration_1d)/1000 as dd_ads_item_pdp_duration_1d
    ,1.000*sum(dd_ads_item_mix_feed_pdp_duration_1d)/1000 as dd_ads_item_mix_feed_pdp_duration_1d
    ,sum(dd_video_landing_livestream_duration_1d) as  dd_video_landing_livestream_duration_1d
    ,sum(dd_item_mix_landing_livestream_duration_1d) as dd_item_mix_landing_livestream_duration_1d
    ,1.000*sum(new_arrival_pdp_duration_1d) /1000 as new_arrival_pdp_duration_1d
    ,1.000*sum(cheapest_pdp_duration_1d) /1000 as cheapest_pdp_duration_1d
from detail_data_${grass_region_without_quote}
group by user_id
